use xiom.io;
fn average(scores: &Vec[Int]) -> Int {
  if scores.len() == 0 { return 0; };
  var sum = 0;
  var i = 0;
  while i < scores.len() {
    sum += scores.get(i).unwrap();
    i += 1;
  };
  sum / scores.len()
}

fn letter_grade(score: Int) -> Str {
  if score >= 90 { return "A"; };
  if score >= 80 { return "B"; };
  if score >= 70 { return "C"; };
  if score >= 60 { return "D"; };
  "F"
}

fn main() -> Int {
  var scores: Vec[Int] = Vec[Int].new();
  scores.push(85); scores.push(92); scores.push(78); scores.push(95);
  let avg = average(&scores);
  io.println(avg.to_str());
  io.println(letter_grade(avg));
  return 0;
}
